import fs from"fs";import path from"path";import sharp from"sharp";const inputDir="./chapter",outputDir="./chapter/optimized";fs.mkdirSync(outputDir,{recursive:!0}),fs.readdirSync(inputDir).forEach((t=>{if(t.match(/\.(jpg|jpeg|png)$/i)){const r=path.join(inputDir,t),i=path.join(outputDir,`${path.parse(t).name}.webp`);sharp(r).resize({width:1400,withoutEnlargement:!0}).webp({quality:92,effort:6,smartSubsample:!0,nearLossless:!0}).withMetadata(!1).toFile(i).then((()=>{console.log(`✅ Optimized: ${t}`)})).catch((r=>{console.error(`❌ Error optimizing ${t}:`,r)}))}}));